const cases = [
  {id:'pass_to_review', snapshot:{assets:{a:{release_gate:'Pass',reconciliation_status:'Done',endpoints:['e']}},endpoints:{e:{release_gate:'Pass',copy_state:'Reconciled'}}}, expect:{result:'PASS',asset:'Review',endpoint:'Review'}},
  {id:'idempotent_review', snapshot:{assets:{a:{release_gate:'Review',reconciliation_status:'In progress',endpoints:['e']}},endpoints:{e:{release_gate:'Review',copy_state:'Review Needed'}}}, expect:{result:'PASS',asset:'Review',endpoint:'Review'}},
  {id:'blocked_asset', snapshot:{assets:{a:{release_gate:'Block',reconciliation_status:'In progress',endpoints:['e']}},endpoints:{e:{release_gate:'Pass',copy_state:'Reconciled'}}}, expect:{result:'PARTIAL',asset:'Block',endpoint:'Review'}},
  {id:'blocked_endpoint', snapshot:{assets:{a:{release_gate:'Pass',reconciliation_status:'Done',endpoints:['e']}},endpoints:{e:{release_gate:'Block',copy_state:'Review Needed'}}}, expect:{result:'PARTIAL',asset:'Review',endpoint:'Block'}},
  {id:'missing_relation', snapshot:{assets:{a:{release_gate:'Pass',reconciliation_status:'Done',endpoints:[]}},endpoints:{}}, expect:{result:'PARTIAL',asset:'Review'}},
  {id:'unknown_canonical', blocked:'canonical', expect:{result:'BLOCKED'}},
  {id:'unknown_trigger', blocked:'trigger', expect:{result:'BLOCKED'}}
];

function run(c) {
  const s = JSON.parse(JSON.stringify(c.snapshot || {assets:{},endpoints:{}}));
  if (c.blocked) return {id:c.id,result:'BLOCKED',state:s};
  const a=s.assets.a;
  let result='PASS';
  if (a.release_gate==='Block') result='PARTIAL';
  else { a.release_gate='Review'; a.reconciliation_status='In progress'; }
  if (!a.endpoints || a.endpoints.length===0) result='PARTIAL';
  for (const eid of (a.endpoints||[])) {
    const e=s.endpoints[eid];
    if (!e) { result='PARTIAL'; continue; }
    if (e.release_gate==='Block') result='PARTIAL';
    else { e.release_gate='Review'; e.copy_state='Review Needed'; }
  }
  return {id:c.id,result,state:s};
}

const results=cases.map(c=>{
  const r=run(c);
  const checks=[r.result===c.expect.result];
  if(c.expect.asset) checks.push(r.state.assets.a.release_gate===c.expect.asset);
  if(c.expect.endpoint) checks.push(r.state.endpoints.e.release_gate===c.expect.endpoint);
  return {...r,pass:checks.every(Boolean)};
});
const failed=results.filter(r=>!r.pass);
if(failed.length) throw new Error('PORTABLE_VECTOR_CONFORMANCE_FAILED:'+JSON.stringify(failed));
return [{json:{
  harness:'NDR_PUBLIC_CHANGE_PROPAGATION_N8N_VECTOR_HARNESS_V1',
  mode:'IN_MEMORY_CONFORMANCE_ONLY',
  runtime_state:'NOT_DEPLOYED',
  authority_effect:'NONE_DEPLOYMENT_EVIDENCE_ONLY',
  conformance_schema:'NDR_PUBLIC_CHANGE_PROPAGATION_CONFORMANCE_V1',
  total:results.length,
  passed:results.length-failed.length,
  failed:failed.length,
  result:failed.length?'FAIL':'PASS',
  results
}}];
